await (async function consumeArtifact(){
  const {readFileSync,existsSync}=await import('node:fs')
  const {spawnSync}=await import('node:child_process')
  const {createHash}=await import('node:crypto')
  const {networkInterfaces}=await import('node:os')
  const {strict:assert}=await import('node:assert')
  const expected=JSON.parse(process.env.DEPOT_VM_EXPECTED_BINDING)
  const receipt=JSON.parse(readFileSync('/artifact/receipt.json','utf8'))
  for(const field of ['cohort','harnessRevision','sourceRevision','caseManifestSha256'])assert.deepEqual(receipt[field],expected[field])
  assert.equal(createHash('sha256').update(readFileSync('/artifact/index.mjs')).digest('hex'),receipt.artifact.sha256)
  assert.equal('v'+process.versions.node,receipt.node.version)
  assert(!existsSync('/source')&&!existsSync('/harness')&&!existsSync('/node_modules')&&!existsSync('/artifact/node_modules'))
  assert(!process.env.NODE_PATH&&!process.env.GH_TOKEN&&!process.env.DEPOT_TOKEN)
  const interfaces=networkInterfaces()
  assert(Object.values(interfaces).flat().every(address=>address.internal),'Artifact consumer must have only internal network interfaces')
  const limits={memoryMax:readFileSync('/sys/fs/cgroup/memory.max','utf8').trim(),cpuMax:readFileSync('/sys/fs/cgroup/cpu.max','utf8').trim(),pidsMax:readFileSync('/sys/fs/cgroup/pids.max','utf8').trim()}
  assert.equal(limits.memoryMax,'2147483648');assert.equal(limits.cpuMax,'200000 100000');assert.equal(limits.pidsMax,'512')
  const results=[]
  for(const [id,args,fragments] of [['bundle-help',['--help'],['vmsync','import','boot','sync','status','list','config']],['bundle-list-empty',['list'],['no managed VMs']]]){
   const result=spawnSync('/usr/bin/node',['/artifact/index.mjs',...args],{cwd:'/artifact',encoding:'utf8',timeout:15000,maxBuffer:4*1024*1024})
   results.push({id,args,exitCode:result.status,signal:result.signal,error:result.error?.message,stdout:result.stdout??'',stderr:result.stderr??'',expectedStdoutFragments:fragments})
   assert.equal(result.status,0,`${id}: ${result.stderr}`)
   for(const fragment of fragments)assert((result.stdout??'').includes(fragment),`${id}: missing ${fragment}`)
  }
  const memoryPeak=Number(readFileSync('/sys/fs/cgroup/memory.peak','utf8').trim())
  console.log(JSON.stringify({artifactSha256:receipt.artifact.sha256,cohort:receipt.cohort,sourceRevision:receipt.sourceRevision,harnessRevision:receipt.harnessRevision,caseManifestSha256:receipt.caseManifestSha256,node:process.versions.node,limits,memoryPeak,memoryPeakFraction:memoryPeak/Number(limits.memoryMax),networkInterfaces:Object.keys(interfaces),results}))
 })()

